/**
 * @distilled.cloud/mollie -- Mollie API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-mollie/specs/specs.yaml`. Everything else in this
 * folder is hand-written.
 *
 * Mollie is one service, so its operations are exported straight off the
 * package root.
 *
 * @example
 * ```ts
 * import * as Mollie from "@distilled.cloud/mollie";
 *
 * const payment = yield* Mollie.getPayment({ paymentId: "tr_7UhSN1zuXS" });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { MollieProtocol, type MollieOpError, type MollieOpContext } from "./protocol.ts";
export { paginateNextPage } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/mollie.ts";
// The service-local typed error classes shadow the same-named shared ones
// from ./errors.ts -- the operations raise the service-local classes.
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/mollie.ts";
